// Визуальные шаблоны. Здесь нет расчёта турнира или сохранения данных.
// Исходные selectors и tokens подключаются страницей потребителя.
export const Style=Object.freeze({primary:Symbol('primary'),secondary:Symbol('secondary'),danger:Symbol('danger'),icon:Symbol('icon'),accentIcon:Symbol('accentIcon'),link:Symbol('link')});
export const State=Object.freeze({default:Symbol('default'),hover:Symbol('hover'),pressed:Symbol('pressed'),focus:Symbol('focus'),disabled:Symbol('disabled'),invalid:Symbol('invalid')});
export const Density=Object.freeze({mobile:Symbol('mobile'),desktop:Symbol('desktop')});
export const Identity=Object.freeze({inline:Symbol('inline'),fighter:Symbol('fighter'),profile:Symbol('profile')});
export const Row=Object.freeze({roster:Symbol('roster'),assignment:Symbol('assignment'),ranking:Symbol('ranking'),history:Symbol('history')});
let serial=0;
const uid=()=>`kit-control-${++serial}`;
export const esc=(v)=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
/** @param {string} name ID исходного symbol. @param {string} extra CSS presentation classes. */
export function icon(name='arrow',extra=''){return `<svg class="icon ${esc(extra)}" aria-hidden="true"><use href="#${esc(name)}"/></svg>`;}
/** @param {{text?:string,iconName?:string,style?:symbol,state?:symbol,full?:boolean}} p */
export function button({text='Продолжить',iconName='',style=Style.primary,state=State.default,full=true}={}){
 const cls=style===Style.primary?'primary-action':style===Style.secondary?'secondary-action':style===Style.danger?'flow-danger-action':style===Style.icon?'orb':style===Style.accentIcon?'orb profile-save':'flow-text-link';
 const round=style===Style.icon||style===Style.accentIcon;
 const demo=state===State.hover?'kit-hover':state===State.pressed?'kit-pressed':state===State.focus?'kit-focus':'';
 return `<button type="button" data-kit-part="Button" class="${cls} ${demo}${full&&!round?' kit-full':''}" ${state===State.disabled?'disabled':''} ${round?`aria-label="${esc(text)}" title="${esc(text)}"`:''}>${!round?esc(text):''}${iconName?icon(iconName):''}</button>`;
}
/** @param {{label?:string,value?:string,multiline?:boolean,state?:symbol,readonly?:boolean,error?:string}} p */
export function field({label='Название',value='Пятничный турнир',multiline=false,state=State.default,readonly=false,error=''}={}){
 const id=uid(),errorId=uid(); const attrs=`id="${id}" ${readonly?'readonly':''} ${state===State.disabled?'disabled':''} ${state===State.invalid?'aria-invalid="true"':''} ${error?`aria-describedby="${errorId}"`:''} class="${state===State.focus?'kit-focus':''}"`;
 return `<div class="field" data-kit-part="Field"><label for="${id}">${esc(label)}</label>${multiline?`<textarea ${attrs}>${esc(value)}</textarea>`:`<input ${attrs} value="${esc(value)}">`}${error?`<p id="${errorId}" class="error-copy">${icon('alert')}${esc(error)}</p>`:''}</div>`;
}
export function select({label='Оформление',disabled=false}={}){const id=uid();return `<div class="field" data-kit-part="Select"><label for="${id}">${esc(label)}</label><div class="settings-select-shell"><select id="${id}" ${disabled?'disabled':''}><option>Тёмное</option><option>Светлое</option><option>Как в системе</option></select>${icon('chevron')}</div></div>`;}
export function segmented({selected=0}={}){return `<div data-kit-part="SegmentedChoice" class="flow-options" aria-label="Формат турнира">${['DE','SE','RR'].map((x,i)=>`<a href="#components" ${i===selected?'aria-current="page"':''}>${x}</a>`).join('')}</div>`;}
export function scoreChoice({selected=0}={}){return `<div data-kit-part="ScoreChoice" class="flow-score-options" aria-label="Демонстрационный выбор счёта">${['1 : 0','0 : 1'].map((x,i)=>`<button type="button" aria-pressed="${i===selected}" class="${i===selected?'is-selected':''}">${x}</button>`).join('')}</div>`;}
export function stepper({label='Основная сетка',value=1,min=1,max=10,score=false}={}){const id=uid();return `<div class="flow-ft-field" data-kit-part="NumberStepper"><span class="flow-field-label" id="${id}">${esc(label)}</span><div class="${score?'result-score-stepper':'flow-ft-stepper'}" role="group" aria-labelledby="${id}"><button type="button" aria-label="Уменьшить ${esc(label)}" ${value<=min?'disabled':''}>${icon('minus')}</button>${score?`<input type="number" min="${min}" max="${max}" value="${value}" aria-label="${esc(label)}">`:`<output>FT${value}</output>`}<button type="button" aria-label="Увеличить ${esc(label)}" ${value>=max?'disabled':''}>${icon('plus')}</button></div></div>`;}
export function avatar({initials='SZ',tone='ice',portrait=false,profile=false}={}){return `<span data-kit-part="Avatar" class="${profile?'profile-monogram':`flow-avatar ${esc(tone)} ${portrait?'portrait':''}`}" aria-hidden="true">${esc(initials)}</span>`;}
export function identity({name='Иван',character='Sub-Zero',initials='SZ',tone='ice',layout=Identity.inline,winner=false}={}){
 if(layout===Identity.profile)return `<div data-kit-part="Identity" class="profile-current-identity">${avatar({initials:name.slice(0,1),profile:true})}<div><h3>${esc(name)}</h3></div></div>`;
 if(layout===Identity.fighter)return `<div data-kit-part="Identity" class="flow-fighter ${winner?'result-winner':''}">${avatar({initials,tone,portrait:true})}<strong>${esc(character)}</strong><span>${esc(name)}</span></div>`;
 return `<span data-kit-part="Identity" class="flow-person">${avatar({initials,tone})}<span><strong>${esc(character)}</strong><small>${esc(name)}</small></span></span>`;
}
export function metric({value='12',label='Турниры',accent=false,desktop=false,index=0}={}){
 const content=`<dl><div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div></dl>`;
 if(accent){const inner=`<div class="profile-achievement">${icon('trophy')}${content}</div>`;return desktop?`<section data-kit-part="Metric" class="profile-bento-achievement">${inner}</section>`:`<section data-kit-part="Metric">${inner}</section>`;}
 return desktop?`<dl data-kit-part="Metric" class="profile-bento-metric profile-bento-metric-${index}"><div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div></dl>`:`<dl data-kit-part="Metric" class="profile-achievement-secondary kit-single-metric"><div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div></dl>`;
}
export function navigation({text='Настройки',iconName='settings',desktop=false,index=0}={}){return `<a href="#mapping" data-kit-part="NavigationItem" class="profile-menu-item ${desktop?`profile-bento-link profile-bento-link-${index}`:''}">${icon(iconName)}<span>${esc(text)}</span>${icon('chevron','profile-menu-chevron')}</a>`;}
export function header({title='Новый турнир',action=false,trailingIcon='check',accent=true}={}){return `<div data-kit-part="SectionHeader" class="flow-header">${button({style:Style.icon,text:'Назад',iconName:'back'})}<h2>${esc(title)}</h2>${action?button({style:accent?Style.accentIcon:Style.icon,text:accent?'Сохранить':'Редактировать',iconName:trailingIcon}):'<span aria-hidden="true"></span>'}</div>`;}
export function score({left='0',right='0',fixed=false}={}){return fixed?`<div data-kit-part="Score" class="result-fixed-score" aria-label="Счёт победителя">${esc(left)}</div>`:`<div data-kit-part="Score" class="competition-score" aria-label="Текущий счёт ${esc(left)}:${esc(right)}">${esc(left)}<span>:</span>${esc(right)}</div>`;}
export function disclosure({title='Управление турниром',body='Дополнительные действия доступны в контексте турнира.',open=false}={}){return `<details data-kit-part="Disclosure" class="competition-disclosure" ${open?'open':''}><summary>${esc(title)}${icon('chevron')}</summary><div class="competition-disclosure-body">${esc(body)}</div></details>`;}
export function notice({text='Bracket Reset включён всегда.',error=false,inline=false}={}){return `<p data-kit-part="Notice" class="${inline?'error-copy':'flow-notice'} ${error?'danger':''}">${icon(error?'alert':'info')}<span>${esc(text)}</span></p>`;}
export function status({text='В процессе',dot=true,error=false}={}){return `<span data-kit-part="Status" class="${dot?'eyebrow kit-status':`competition-outcome ${error?'is-loss':''}`}">${dot?'<span class="live-dot" aria-hidden="true"></span>':''}${esc(text)}</span>`;}
export function row({kind=Row.assignment,name='Иван',character='Sub-Zero',initials='SZ',tone='ice',revealed=false,place='2',points='',title='Пятничный турнир',metadata='14 октября · DE'}={}){
 if(kind===Row.roster)return `<ul class="flow-roster-guests kit-list-reset"><li data-kit-part="ListRow" class="flow-player-row flow-roster-gesture ${revealed?'is-revealed':''}"><span class="flow-person">${avatar({initials:name.slice(0,1),tone:'unassigned'})}<strong>${esc(name)}</strong></span><a class="flow-roster-remove" href="#mapping" aria-label="Удалить участника ${esc(name)}">Удалить</a></li></ul>`;
 if(kind===Row.history)return `<a href="#mapping" data-kit-part="ListRow" class="flow-history-row"><span class="flow-kicker">${esc(metadata)}</span><h3>${esc(title)}</h3><div class="flow-history-winner">${icon('trophy')}${identity({name,character,initials,tone})}${icon('chevron')}</div></a>`;
 if(kind===Row.ranking)return `<ol class="flow-ranking kit-rank-context"><li data-kit-part="ListRow" class="kit-ranking-plain">${points?'':`<span class="flow-place">${esc(place)}</span>`}${identity({name,character,initials,tone})}${points?`<span class="competition-rank-points"><strong>${esc(points)}</strong><small>очки</small></span>`:''}</li></ol>`;
 return `<div data-kit-part="ListRow" class="flow-player-row">${identity({name,character,initials,tone})}</div>`;
}
export function standings(){return `<div class="flow-table-wrap" data-kit-part="Table"><table class="flow-standings"><caption>Основной этап · итоговые очки</caption><thead><tr><th scope="col">Участник</th><th scope="col">Очки</th><th scope="col"><abbr title="Сыграно матчей">М</abbr></th></tr></thead><tbody>${[['Sub-Zero','Иван','SZ','ice'],['Scorpion','Алексей','SC','fire'],['Kitana','Мария','KT','fan']].map(([character,name,initials,tone])=>`<tr><th scope="row">${identity({character,name,initials,tone})}</th><td>3</td><td>2</td></tr>`).join('')}</tbody></table></div>`;}
export function bracketNode({current=false,pending=false}={}){return `<button type="button" data-kit-part="BracketNode" class="bracket-map-match ${current?'is-current':''}"><span class="bracket-map-match-label">W${pending?'6':current?'5':'1'} · ${pending?'Полуфинал':current?'Сейчас':'Раунд 1'}</span>${pending?'<span class="bracket-map-unknown">Победитель W3</span><span class="bracket-map-unknown">Победитель W4</span>':[['SZ','Sub-Zero','Иван'],['SC','Scorpion','Алексей']].map(([a,c,n])=>`<span class="bracket-map-player"><span class="bracket-map-avatar">${a}</span><span><strong>${c}</strong><small>${n}</small></span></span>`).join('')}</button>`;}
export function dialog({title='Снять Алексея с турнира?',text='Прошлые результаты сохранятся. Вернуть игрока в турнир нельзя.',action='Снять участника',disabled=false}={}){const id=uid();return `<section data-kit-part="Dialog" class="flow-alert kit-dialog" role="group" aria-labelledby="${id}"><h2 id="${id}">${esc(title)}</h2><p>${esc(text)}</p><div class="flow-alert-actions">${button({text:action,style:Style.danger,state:disabled?State.disabled:State.default})}${button({text:'Отмена',style:Style.secondary})}</div></section>`;}
export function share({url='http://host.local/spectator',label='Только просмотр'}={}){return `<div data-kit-part="ShareLink" class="spectator-link"><span class="flow-address">${esc(label)}<br>${esc(url)}</span>${button({style:Style.icon,text:'Скопировать ссылку',iconName:'share-link'})}</div>`;}
export function surface(content,{raised=false}={}){return `<div data-kit-part="Surface" class="flow-panel ${raised?'kit-surface-raised':''}">${content}</div>`;}
// Reusable recipes: те же primitives используются в листе и обратной сборке.
export function formatSelector(){return `<section class="flow-stack flow-format-field"><h3 class="flow-field-label">Формат</h3>${segmented()}<div><h2>Double Elimination</h2><p class="flow-caption">Два поражения — вылет</p></div></section>`;}
export function recent({desktop=false}={}){return `<a class="flow-last-result ${desktop?'profile-bento-recent':''}" href="#mapping"><span class="flow-kicker">Последний турнир</span><span class="flow-result-place">2<span>место</span></span><h3>Пятничный турнир</h3>${identity()}<p class="flow-caption">14 октября · Double Elimination</p></a>`;}
export function setupRecipe(density){const desktop=density===Density.desktop;const fieldName=field();const ft1=stepper(),ft2=stepper({label:'Grand Final / Reset'});return `<article class="kit-rebuild flow-screen ${desktop?'desktop-screen':''}" ${desktop?'data-desktop-screen="setup-de"':''} data-rebuild="setup"><div class="screen-content">${desktop?`<div class="desktop-page-header">${header()}</div><div class="bento-setup"><div class="desktop-tile bento-setup-name">${fieldName}</div><div class="desktop-tile bento-setup-format">${formatSelector()}</div><div class="desktop-tile bento-setup-ft">${ft1}</div><div class="desktop-tile bento-setup-ft">${ft2}</div>${notice()}<div class="desktop-command">${button({text:'К участникам',iconName:'arrow'})}</div></div>`:`${header()}${fieldName}${formatSelector()}${surface(ft1+ft2)}${notice()}`}</div>${desktop?'':`<div class="action-dock">${button({text:'К участникам',iconName:'arrow'})}</div>`}</article>`;}
export function profileRecipe(density){const desktop=density===Density.desktop;const nav=[['Настройки','settings'],['О приложении','info'],['Связь','contact']].map(([text,iconName],index)=>navigation({text,iconName,desktop,index})).join('');return `<article class="kit-rebuild profile-current profile-current-view ${desktop?'desktop-screen':''}" ${desktop?'data-desktop-screen="profile-refined-view"':''} data-rebuild="profile"><div class="screen-content">${header({title:'Профиль',action:true,trailingIcon:'edit',accent:false})}${desktop?`<div class="profile-bento-grid"><section class="profile-bento-identity">${identity({layout:Identity.profile})}</section>${metric({value:'3',label:'Победы в турнирах',accent:true,desktop:true})}${metric({desktop:true})}${metric({value:'28',label:'Схватки',desktop:true,index:1})}${recent({desktop:true})}<nav class="profile-bento-links" aria-label="Разделы профиля">${nav}</nav></div>`:`${identity({layout:Identity.profile})}${recent()}<section class="profile-stats-achievement">${metric({value:'3',label:'Победы в турнирах',accent:true})}<div class="kit-metric-pair">${metric()}${metric({value:'28',label:'Схватки'})}</div></section><nav class="profile-menu" aria-label="Разделы профиля">${nav}</nav>`}</div></article>`;}
